import pprint
import sys
from robot.api import logger as r_logger
import requests
import re
import os
import shutil
import logging
from collections import namedtuple
import pexpect
from .build_decoding_classes_from_standard import get_version_of_standard
from .py3_string import py3_string
from taf.internal.wireshark.installation import install_plugin
import ta_pcmd


TSHARK_BIN_PLUGIN_PATH = '/home/ute/.local/lib/wireshark/plugins/{version}/epan/'
PLUGIN_TMP_PATH = os.path.join(os.sep, 'tmp', 'temp_plugin')
PLUGIN_FOLDER_NAME = 'tshark_nsetap_plugins'
PLUGINS_TO_LOAD_FOLDER_PATH = os.path.join(os.path.dirname(ta_pcmd.__file__), PLUGIN_FOLDER_NAME)
PLUGINS_TO_LOAD_REMOTE_PATH = 'http://files.ute.nsn-rdnet.net/builds/wireshark'
TSHARK_VERSION_RE = re.compile(r'[-v](\d\.\d).*?\+(.*?)[\.-].*?')
PLUGIN_VERSION_RE = re.compile(r'nsetap([x]?)-(\d\.\d)-(\d\.\d+\.\d)(?:-\d)?\+(.*?)\.so')
TSHARK_VERSION_CMD = 'tshark --version'
NSETAP_STANDARD_AND_PLUGIN_NAMES = {'nsetap': 'nsetap', 'nsetap-x': 'nsetapx'}

logger = logging.getLogger('tshark_plugin_configurator')

version = namedtuple('version', 'file system')


class plugin_file(object):
    def __init__(self, name, location):
        self.name = name
        self.location = location
        self.technology = self._get_technology()
        self.tshark_version = self._get_version_for_tshark()
        self.file_version = self._get_file_version()
        self.system_version = self._get_system_version()

    def _get_technology(self):
        return '5G' if PLUGIN_VERSION_RE.search(self.name).group(1) else '4G'

    def _get_version_for_tshark(self):
        return PLUGIN_VERSION_RE.search(self.name).group(2)

    def _get_file_version(self):
        return PLUGIN_VERSION_RE.search(self.name).group(3)

    def _get_system_version(self):
        return PLUGIN_VERSION_RE.search(self.name).group(4)

    def __gt__(self, other):
        return int(self.file_version.replace('.', '')) > int(other.file_version.replace('.', ''))

    def __str__(self):
        return self.name


def load_tshark_bin_plugin(load_from=PLUGINS_TO_LOAD_REMOTE_PATH, technology='4G'):
    '''
    Copy tshark plugin from specified location to tshark plugin folder.
    Assumes that provided folder contains only one plugin. Multiple files
    in folder will be treated as different plugin versions. Only single file
    will be copied to destination folder. Part of the file name must be:
    - version of tshark the plugin is for, i.e. '2.6'
    - debian version the plugin is for, i.e. 'jessie'
    '''
    tshark_version = get_tshark_version()
    logger.debug('Tshark version: {}'.format(tshark_version))
    newest_matching_tshark_plugin_version = get_newest_matching_tshark_plugin_version(load_from, tshark_version, technology)
    copy_newest_plugin_into_tshark_bin_plugin_folder(newest_matching_tshark_plugin_version, tshark_version)


def load_tshark_plugin_via_wireshark_script(technology='4G'):
    proto_version = 'nsetap' if technology == '4G' else 'nsetap-x'
    current_lib_standard_version = get_version_of_standard(proto_version)
    installed = install_plugin(NSETAP_STANDARD_AND_PLUGIN_NAMES[proto_version], 'latest')
    if current_lib_standard_version not in installed:
        message = 'Library supported version: {} does not match installed latest plugin: {}\n' \
                  'Newly added records may be parsed wrongly'.format(current_lib_standard_version,
                                                                     installed)
        print(message)
        try:
            r_logger.warn(message)
        except Exception:
            pass


def get_tshark_version():
    '''
    Return tshark version as tuple.
    '''
    output = pexpect.run(TSHARK_VERSION_CMD)
    output = py3_string(output)
    tshark_ver = TSHARK_VERSION_RE.search(output).group(1)
    os_ver = TSHARK_VERSION_RE.search(output).group(2)
    return version(file=tshark_ver, system=os_ver)


def get_newest_matching_tshark_plugin_version(load_from, tshark_version, technology='4G'):
    '''
    Selects those plugins that match tshark and system version
    and then selects newest one among them and returns it.
    '''
    plugins = get_all_plugins(load_from)
    matching_tshark_plugins = get_plugins_matching_tshark_version(plugins, tshark_version, technology)
    logger.debug(matching_tshark_plugins)
    newest_plugin = get_newest_plugin(matching_tshark_plugins)
    logger.debug('Found plugin matching tshark and system version: {}'.format(newest_plugin))
    return newest_plugin


def copy_newest_plugin_into_tshark_bin_plugin_folder(plugin, tshark_version):
    '''
    Copies plugin into tshark plugin folder.
    '''
    tshark_bin_plugin_path = TSHARK_BIN_PLUGIN_PATH.format(version=tshark_version.file)
    create_plugin_version_folder(tshark_version)
    if 'http' in plugin.location:
        if sys.version_info[0] >= 3:
            mode = 'wb'
        else:
            mode = 'w'
        with open(PLUGIN_TMP_PATH, mode=mode) as temp_file:
            temp_file.write(_get_url_content(plugin.location, raw=True))
        src_path = PLUGIN_TMP_PATH
    else:
        src_path = os.path.join(plugin.location, plugin.name)
    _copy_plugin(src=src_path,
                 dst=os.path.join(tshark_bin_plugin_path, plugin.name))


def get_all_plugins(location):
    '''
    Retusn a list of tshark plugins files from specified location.
    '''
    if 'http' in location:
        all_plugins = []
        remote_plugins = _list_plugins_remote_location(location)
        for plug_type in remote_plugins:
            for plug_info in remote_plugins[plug_type]['plugins']:
                all_plugins.append(plugin_file(plug_info['name'], plug_info['url']))
        return all_plugins
    else:
        return [plugin_file(file_name, plugin_folder) for plugin_folder, file_name in _list_plugin_folder(location)]


def get_plugins_matching_tshark_version(plugins, tshark_version, technology='4G'):
    '''
    Returns plugins matching tshark version.
    '''
    matching_plugins = [plugin for plugin in plugins if
                        plugin.tshark_version == tshark_version.file
                        and plugin.system_version == tshark_version.system
                        and plugin.technology == technology]
    if not matching_plugins:
        tshark_bin_plugin_path = TSHARK_BIN_PLUGIN_PATH.format(version=tshark_version.file)
        raise AttributeError("Could not find tshark {} plugin file (in folder '{}')"
                             " that meets tshark version requirements: {}".format(technology,
                                                                                  tshark_bin_plugin_path,
                                                                                  tshark_version))
    return matching_plugins


def get_newest_plugin(plugins):
    '''
    Returns one newest plugin.
    '''
    return max(plugins)


def create_plugin_version_folder(tshark_version):
    '''
    Creates tshark plugin folder.
    '''
    tshark_bin_plugin_path = TSHARK_BIN_PLUGIN_PATH.format(version=tshark_version.file)
    if not os.path.exists(tshark_bin_plugin_path):
        os.makedirs(tshark_bin_plugin_path)
        logger.debug("Folder created: '{}'".format(tshark_bin_plugin_path))
    else:
        logger.debug("Folder already exists: '{}'".format(tshark_bin_plugin_path))


def _list_plugin_folder(folder):
    for dirname, _, filenames in os.walk(folder):
        for file_name in filenames:
            yield (dirname, file_name)


def _list_plugins_remote_location(location):
    return _get_remote_page_links(location)


def _copy_plugin(src, dst):
    if not os.path.exists(dst):
        shutil.copyfile(src, dst)
        logger.debug("File created: '{}'".format(dst))
    else:
        logger.debug("File already exists: '{}'".format(dst))


def _get_url_content(url, raw=False):
    response = requests.get(url)
    content = response.content
    if raw is False:
        if sys.version_info[0] >= 3:
            content = content.decode(errors='replace')
        return requests.utils.unquote(content)
    else:
        return content


def _find_links(url):
    all_links = sorted(re.findall('(?<=<a href=")[^"]*', _get_url_content(url)))
    return all_links


def _get_remote_page_links(url):
    plugins = {}
    all_plugin_types = [plugin for plugin in _find_links(url) if 'nsetap' in plugin]
    for plug_type in all_plugin_types:
        plugins[plug_type.strip('/')] = {'url': "/".join([url, plug_type]), 'plugins': []}
    for single_plugin in sorted(plugins.keys(), reverse=True):
        plugs = [plugin for plugin in _find_links(plugins[single_plugin]['url']) if 'nsetap' in plugin]
        for plug in plugs:
            plugins[single_plugin]['plugins'].append({'name': plug, 'url': "/".join([plugins[single_plugin]['url'], plug])})
    logger.debug('Parsed plugins:\n{}'.format(pprint.pformat(plugins)))
    return plugins
